mapper.select:
SELECT p.id, p.name, p.description, p.owner_id, p.progress, p.is_deleted, p.is_archived, p.created_at, p.updated_at, COALESCE(p.group_id, 0) AS groupId FROM pm_project p LEFT JOIN pm_project_member pm ON p.id = pm.project_id AND pm.user_id = #{userId} WHERE p.is_deleted = 0
AND COALESCE(p.group_id, 0) = #{groupId}
AND pm.user_id = #{userId}
AND COALESCE(p.group_id, 0) = #{groupId}
AND p.is_archived = #{archived}
ORDER BY p.updated_at DESC
